def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Identify the fill value (most common value in interior)
    fill_val = grid[1][1]

    # Get corner/header values
    top_left = grid[0][0]
    top_right = grid[0][cols-1]
    bottom_left = grid[rows-1][0]
    bottom_right = grid[rows-1][cols-1]

    # Find all unique values that are neither fill nor border (most common header value)
    border_val = None
    for v in set(grid[0]):
        if v != fill_val and v != top_left:
            border_val = v
            break

    # Build the logical grid by sampling at regular intervals
    # Determine output dimensions based on interval detection
    interval_rows = []
    for r in range(rows):
        if grid[r][0] != top_left:
            interval_rows.append(r)

    interval_cols = []
    for c in range(cols):
        if grid[0][c] != top_left:
            interval_cols.append(c)

    # Output grid size based on intervals
    if interval_rows and interval_cols:
        output_rows = len(interval_rows)
        output_cols = len(interval_cols)
    else:
        # Estimate from grid dimensions
        output_rows = rows // 5
        output_cols = cols // 5

    # Create output grid
    result = []

    for r_idx in range(output_rows):
        row = []
        if interval_rows:
            rope = interval_rows[r_idx]
        else:
            rope = r_idx * (rows // max(output_rows, 1))

        for c_idx in range(output_cols):
            if interval_cols:
                cpos = interval_cols[c_idx]
            else:
                cpos = c_idx * (cols // max(output_cols, 1))

            val = grid[rope][cpos]
            if val == fill_val:
                row.append(fill_val)
            else:
                row.append(val)

        result.append(row)

    # Adjust for Pair 2 style cases (1x1 output when grid is homogeneous)
    if result[0] == [fill_val] and rows > 20 and cols > 20:
        # Check if this is a single-marker case
        special_vals = set()
